        const mapById = new Map<string, AccountCredential>();
        DEFAULT_ACCOUNT_CREDENTIALS.forEach((d) => mapById.set(d.staffId, d));
        parsed.forEach((p) => mapById.set(p.staffId, p));
        return Array.from(mapById.values());
