  const [customers, setCustomers] = useState<Customer[]>(() => {
    let initialDeletedSet = new Set<string>();
    try {
      const savedDel = localStorage.getItem('365md_v1_deleted_customer_ids');
      if (savedDel) {
        const parsedDel = JSON.parse(savedDel);
        if (Array.isArray(parsedDel)) {
          initialDeletedSet = new Set(parsedDel);
        }
      }
    } catch {
      // ignore
    }
    try {
      const saved = localStorage.getItem(STORAGE_KEYS.CUSTOMERS);
      if (saved) {
        const parsed = reviveTimestamps<Customer>(JSON.parse(saved))
          .filter((c) => c && c.customerId && !initialDeletedSet.has(c.customerId))
          .map((c) => ({
            ...c,
            note:
              (c.note || '')
                .replace(/từ\s+KiotViet/gi, 'hệ thống')
                .replace(/KiotViet/gi, '')
                .replace(/\s+/g, ' ')
                .trim() || 'Khách hàng hệ thống 365MD',
          }));
        if (parsed.length > 0) return parsed;
      }
    } catch {
      // ignore
    }
    return buildDefaultCustomers().filter((c) => !initialDeletedSet.has(c.customerId));
  });

