  const handleSaveSupplierToCatalog = async (
    nameRaw?: string,
    phoneRaw?: string,
    extraFields?: {
      address?: string;
      companyName?: string;
      taxCode?: string;
      hasContract?: 'Có' | 'Không';
      contractDate?: string;
    }
  ) => {
    const cleanName = (nameRaw !== undefined ? nameRaw : newSupplierNameInput).trim().slice(0, 100);
    const cleanPhone = (phoneRaw !== undefined ? phoneRaw : newSupplierPhoneInput).trim().slice(0, 32);
    if (!cleanName) {
      notify('error', 'Vui lòng nhập Tên nhà cung cấp trước khi nhấn Save.');
      return;
    }
    const existing = editingSupplierCatalogId
      ? supplierCatalog.find((s) => s.supplierId === editingSupplierCatalogId) ||
        supplierCatalog.find((s) => s.name.toLowerCase() === cleanName.toLowerCase())
      : supplierCatalog.find((s) => s.name.toLowerCase() === cleanName.toLowerCase());

    const supplierId =
      existing?.supplierId ||
      `sup_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    const nowStr = new Date().toLocaleDateString('vi-VN');

    const cleanAddress = (
      extraFields?.address !== undefined
        ? extraFields.address
        : nameRaw !== undefined
        ? existing?.address || ''
        : newSupplierAddressInput
    )
      .trim()
      .slice(0, 250);
    const cleanCompany = (
      extraFields?.companyName !== undefined
        ? extraFields.companyName
        : nameRaw !== undefined
        ? existing?.companyName || ''
        : newSupplierCompanyInput
    )
      .trim()
      .slice(0, 200);
    const cleanTaxCode = (
      extraFields?.taxCode !== undefined
        ? extraFields.taxCode
        : nameRaw !== undefined
        ? existing?.taxCode || ''
        : newSupplierTaxCodeInput
    )
      .trim()
      .slice(0, 64);
    const cleanHasContract: 'Có' | 'Không' =
      extraFields?.hasContract !== undefined
        ? extraFields.hasContract
        : nameRaw !== undefined
        ? existing?.hasContract || 'Không'
        : newSupplierHasContractInput;
    const cleanContractDate = (
      extraFields?.contractDate !== undefined
        ? extraFields.contractDate
        : nameRaw !== undefined
        ? existing?.contractDate || ''
        : newSupplierContractDateInput
    )
      .trim()
      .slice(0, 40);

    const item = {
      supplierId,
      orgId: ORG_ID,
      name: cleanName,
      phone: cleanPhone,
      address: cleanAddress,
      companyName: cleanCompany,
      taxCode: cleanTaxCode,
      hasContract: cleanHasContract,
      contractDate: cleanContractDate,
      updatedAt: nowStr,
    };

    setSupplierCatalog((prev) => {
      const filtered = prev.filter(
        (s) => s.supplierId !== supplierId && s.name.toLowerCase() !== cleanName.toLowerCase()
      );
      const next = [item, ...filtered];
      try {
        localStorage.setItem('365md_v17_supplier_catalog', JSON.stringify(next));
      } catch {
        // ignore
      }
      return next;
    });
    setProdSupplier(cleanName);
    setEditingSupplierCatalogId(null);
    setNewSupplierNameInput('');
    setNewSupplierPhoneInput('');
    setNewSupplierAddressInput('');
    setNewSupplierCompanyInput('');
    setNewSupplierTaxCodeInput('');
    setNewSupplierHasContractInput('Không');
    setNewSupplierContractDateInput('');

    try {
      await setDoc(doc(db, 'suppliers', supplierId), item, { merge: true });
    } catch {
      // ignore offline
    }

    notify(
      'success',
      `Đã lưu Nhà cung cấp [${cleanName}] vào Danh mục Nhà cung cấp!`
    );
  };

  const handleQuickUpdateSupplierContract = async (
    supplierId: string,
    hasContractVal: 'Có' | 'Không'
  ) => {
    const target = supplierCatalog.find((s) => s.supplierId === supplierId);
    if (!target) return;
    const nowStr = new Date().toLocaleDateString('vi-VN');
    const updatedItem = {
      ...target,
      hasContract: hasContractVal,
      updatedAt: nowStr,
    };
    setSupplierCatalog((prev) => {
      const next = prev.map((s) => (s.supplierId === supplierId ? updatedItem : s));
      try {
        localStorage.setItem('365md_v17_supplier_catalog', JSON.stringify(next));
      } catch {
        // ignore
      }
      return next;
    });
    try {
      await setDoc(doc(db, 'suppliers', supplierId), updatedItem, { merge: true });
    } catch {
      // ignore offline
    }
    notify(
      'success',
      `Đã cập nhật Hợp đồng [${hasContractVal}] cho Nhà cung cấp [${target.name}]!`
    );
  };

  const handleDeleteSupplierFromCatalog = async (supplierId: string, supName: string) => {
    setSupplierCatalog((prev) => {
      const next = prev.filter((s) => s.supplierId !== supplierId);
      try {
        localStorage.setItem('365md_v17_supplier_catalog', JSON.stringify(next));
      } catch {
        // ignore
      }
      return next;
    });
    if (prodSupplier === supName) {
      setProdSupplier('');
    }
    try {
      await deleteDoc(doc(db, 'suppliers', supplierId));
    } catch {
      // ignore offline
    }
    notify('info', `Đã xóa Nhà cung cấp [${supName}] khỏi Danh mục Nhà cung cấp.`);
  };

