  const [fixedExpenseItems, setFixedExpenseItems] = useState<FixedExpenseItem[]>(() => {
    const todayStr = new Date().toISOString().slice(0, 10);
    const defaultItems: FixedExpenseItem[] = DEFAULT_FIXED_EXPENSE_NAMES.map((name, idx) => ({
      id: `fixed_exp_${idx + 1}`,
      name,
      amountVnd: 0,
      note: '',
      updatedAt: todayStr,
      isCustom: false,
    }));
    try {
      const saved = localStorage.getItem('365md_v7_fixed_expenses');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          const byName = new Map<string, FixedExpenseItem>();
          parsed.forEach((item: FixedExpenseItem) => {
            if (item && item.name) byName.set(item.name.trim().toLowerCase(), item);
          });
          const merged: FixedExpenseItem[] = defaultItems.map((def) => {
            const existing = byName.get(def.name.toLowerCase());
            if (existing) {
              byName.delete(def.name.toLowerCase());
              return {
                ...def,
                amountVnd: Number(existing.amountVnd) || 0,
                note: existing.note || '',
                updatedAt: existing.updatedAt || todayStr,
              };
            }
            return def;
          });
          byName.forEach((customItem) => {
            merged.push({
              ...customItem,
              amountVnd: Number(customItem.amountVnd) || 0,
              note: customItem.note || '',
              updatedAt: customItem.updatedAt || todayStr,
              isCustom: true,
            });
          });
          return merged;
        }
      }
    } catch {
      // ignore
    }
    return defaultItems;
  });

