  // Đồng bộ Phân quyền Nhân viên (25 quyền) & Mật khẩu Đăng nhập Thời gian thực giữa Bản PC và Bản Mobile qua Firestore & Storage
  useEffect(() => {
    const staffPubQuery = query(collection(db, 'staff_public'), where('orgId', '==', ORG_ID));
    let seededMissing = false;
    const unsubStaffPub = onSnapshot(
      staffPubQuery,
      (snap) => {
        const list = snap.docs
          .map((d) => d.data() as StaffPublicProfile)
          .filter((s) => !LEGACY_DEMO_IDS.staff.includes(s.staffId));
        list.sort((a, b) => a.employeeCode.localeCompare(b.employeeCode));

        if (!seededMissing) {
          seededMissing = true;
          const existingIds = new Set(list.map((s) => s.staffId));
          const defaults = buildDefaultStaff().publicList.map(normalizeStaffProfilePermissions);
          defaults.forEach((defStaff) => {
            if (!existingIds.has(defStaff.staffId)) {
              setDoc(
                doc(db, 'staff_public', defStaff.staffId),
                serializeStaffPublicForFirestore(defStaff),
                { merge: true }
              ).catch(() => {});
            }
          });
          // Đồng bộ mật khẩu chuẩn (đặc biệt admin -> admin123@) lên Firestore nếu bản ghi cũ trên Cloud chưa có passwordPlain hoặc vẫn lưu 123456
          list.forEach((remoteStaff) => {
            const rawPw = typeof remoteStaff.passwordPlain === 'string' ? remoteStaff.passwordPlain.trim() : '';
            const isOldAdminPw =
              (remoteStaff.username?.toLowerCase() === 'admin' || remoteStaff.staffId === 'acc_admin_365md') &&
              (!rawPw || rawPw === '123456');
            if (!rawPw || isOldAdminPw) {
              const normalized = normalizeStaffProfilePermissions(remoteStaff);
              setDoc(
                doc(db, 'staff_public', remoteStaff.staffId),
                serializeStaffPublicForFirestore(normalized),
                { merge: true }
              ).catch(() => {});
            }
          });
        }

        if (list.length > 0) {
          setStaffPublic((prev) => {
            const byId = new Map<string, StaffPublicProfile>();
            prev
              .filter((p) => !LEGACY_DEMO_IDS.staff.includes(p.staffId))
              .forEach((p) => byId.set(p.staffId, normalizeStaffProfilePermissions(p)));
            list.forEach((p) => {
              const existing = byId.get(p.staffId);
              byId.set(
                p.staffId,
                normalizeStaffProfilePermissions({
                  ...(existing || {}),
                  ...p,
                } as StaffPublicProfile)
              );
            });
            const mergedList = Array.from(byId.values());
            // Đồng bộ danh sách credentials với passwordPlain mới nhất từ Firestore
            setCredentials((prevCreds) => {
              const credMap = new Map<string, AccountCredential>();
              DEFAULT_ACCOUNT_CREDENTIALS.forEach((c) => credMap.set(c.staffId, c));
              prevCreds.forEach((c) => {
                if (c.staffId === 'acc_admin_365md' && c.passwordPlain === '123456') {
                  credMap.set(c.staffId, { ...c, passwordPlain: 'admin123@' });
                } else {
                  credMap.set(c.staffId, c);
                }
              });
              mergedList.forEach((s) => {
                const pw = resolveStaffPassword(s);
                credMap.set(s.staffId, {
                  staffId: s.staffId,
                  username: s.username,
                  passwordPlain: pw,
                });
              });
              return Array.from(credMap.values());
            });
            return mergedList;
          });
        }
      },
      () => {
        // Fallback to localStorage if offline
      }
    );

    // Đồng bộ thời gian thực danh sách hàng hóa (products) trên mọi thiết bị Điện thoại (iOS/Android) & PC
    const prodRealtimeQuery = query(collection(db, 'products'), where('orgId', '==', ORG_ID));
    const unsubProdRealtime = onSnapshot(
      prodRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        const validDocs: Product[] = [];
        snap.docs.forEach((d) => {
          const raw = d.data() as Product;
          if (!raw || !raw.productId) return;
          if (isLegacyOldWarehouseId(raw.productId)) {
            deleteDoc(doc(db, 'products', d.id)).catch(() => {});
            return;
          }
          validDocs.push(
            sanitizeProductSellPrice({
              ...raw,
              supplier: normalizeSupplierShortName(raw.supplier),
              unit: normalizeProductUnit(raw),
            })
          );
        });
        if (validDocs.length === 0) return;
        setProducts((prev) => {
          const byId = new Map<string, Product>();
          prev
            .filter((p) => !isLegacyOldWarehouseId(p.productId))
            .forEach((p) => byId.set(p.productId, sanitizeProductSellPrice(p)));
          validDocs.forEach((p) => byId.set(p.productId, sanitizeProductSellPrice(p)));
          const merged = Array.from(byId.values());
          try {
            localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {
        // Fallback to localStorage if offline
      }
    );

    const handleStorageSync = (e: StorageEvent) => {
      if (e.key === STORAGE_KEYS.STAFF_PUB && e.newValue) {
        try {
          const parsed = reviveTimestamps<StaffPublicProfile>(JSON.parse(e.newValue))
            .filter((s) => !LEGACY_DEMO_IDS.staff.includes(s.staffId))
            .map(normalizeStaffProfilePermissions);
          if (parsed.length > 0) {
            setStaffPublic(parsed);
          }
        } catch {
          // ignore
        }
      }
      if (e.key === STORAGE_KEYS.CREDENTIALS && e.newValue) {
        try {
          const parsedCreds: AccountCredential[] = JSON.parse(e.newValue);
          if (Array.isArray(parsedCreds) && parsedCreds.length > 0) {
            setCredentials(parsedCreds);
          }
        } catch {
          // ignore
        }
      }
      if (e.key === STORAGE_KEYS.PRODUCTS && e.newValue) {
        try {
          const parsedProds = reviveTimestamps<Product>(JSON.parse(e.newValue))
            .filter((p) => !isLegacyOldWarehouseId(p.productId))
            .map(sanitizeProductSellPrice);
          if (parsedProds.length > 0) {
            setProducts(parsedProds);
          }
        } catch {
          // ignore
        }
      }
    };
    window.addEventListener('storage', handleStorageSync);

    const supRealtimeQuery = query(collection(db, 'suppliers'), where('orgId', '==', ORG_ID));
    const unsubSupRealtime = onSnapshot(
      supRealtimeQuery,
      (snap) => {
        const docs = snap.docs
          .map(
            (d) =>
              d.data() as {
                supplierId: string;
                orgId: string;
                name: string;
                phone: string;
                address?: string;
                companyName?: string;
                taxCode?: string;
                hasContract?: 'Có' | 'Không';
                contractDate?: string;
                updatedAt: string;
              }
          )
          .filter((s) => s && s.supplierId && s.name);
        setSupplierCatalog((prev) => {
          if (docs.length === 0 && prev.length === 0) return prev;
          const byName = new Map<
            string,
            {
              supplierId: string;
              orgId: string;
              name: string;
              phone: string;
              address?: string;
              companyName?: string;
              taxCode?: string;
              hasContract?: 'Có' | 'Không';
              contractDate?: string;
              updatedAt: string;
            }
          >();
          prev.forEach((s) => byName.set(s.name.toLowerCase(), s));
          docs.forEach((s) => {
            const existing = byName.get(s.name.toLowerCase());
            byName.set(s.name.toLowerCase(), {
              ...(existing || {}),
              ...s,
            });
          });
          const merged = Array.from(byName.values());
          try {
            localStorage.setItem('365md_v17_supplier_catalog', JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {
        // ignore offline
      }
    );

    // Đồng bộ thời gian thực toàn bộ Hóa đơn bán hàng (sales_orders) từ mọi tài khoản Nhân viên về Admin
    const ordRealtimeQuery = query(collection(db, 'sales_orders'), where('orgId', '==', ORG_ID));
    const unsubOrdRealtime = onSnapshot(
      ordRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        const list = snap.docs
          .map((d) => d.data() as SalesOrder)
          .filter((o) => o && o.orderId && !LEGACY_DEMO_IDS.sales_orders.includes(o.orderId));
        if (list.length === 0) return;
        setOrders((prev) => {
          const byId = new Map<string, SalesOrder>();
          prev.forEach((o) => byId.set(o.orderId, o));
          list.forEach((o) => byId.set(o.orderId, o));
          const merged = Array.from(byId.values());
          merged.sort((a, b) => (b.createdAt?.toMillis?.() || 0) - (a.createdAt?.toMillis?.() || 0));
          try {
            localStorage.setItem(STORAGE_KEYS.ORDERS, JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {}
    );

    // Đồng bộ thời gian thực Phiếu xuất/nhập kho (stock_movements) từ mọi tài khoản Nhân viên về Admin
    const movRealtimeQuery = query(collection(db, 'stock_movements'), where('orgId', '==', ORG_ID));
    const unsubMovRealtime = onSnapshot(
      movRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        const list = snap.docs
          .map((d) => d.data() as StockMovement)
          .filter((m) => m && m.movementId && !LEGACY_DEMO_IDS.stock_movements.includes(m.movementId));
        if (list.length === 0) return;
        setMovements((prev) => {
          const byId = new Map<string, StockMovement>();
          prev.forEach((m) => byId.set(m.movementId, m));
          list.forEach((m) => byId.set(m.movementId, m));
          const merged = Array.from(byId.values());
          merged.sort((a, b) => (b.createdAt?.toMillis?.() || 0) - (a.createdAt?.toMillis?.() || 0));
          try {
            localStorage.setItem(STORAGE_KEYS.MOVEMENTS, JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {}
    );

    // Đồng bộ thời gian thực Phiếu Thu / Chi Sổ quỹ (cash_vouchers) từ mọi tài khoản Nhân viên về Admin
    const vchRealtimeQuery = query(collection(db, 'cash_vouchers'), where('orgId', '==', ORG_ID));
    const unsubVchRealtime = onSnapshot(
      vchRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        const legacyVouchers = (LEGACY_DEMO_IDS as Record<string, string[]>).cash_vouchers || [];
        const list = snap.docs
          .map((d) => d.data() as CashVoucher)
          .filter((v) => v && v.voucherId && !legacyVouchers.includes(v.voucherId));
        if (list.length === 0) return;
        setCashVouchers((prev) => {
          const byId = new Map<string, CashVoucher>();
          prev.forEach((v) => byId.set(v.voucherId, v));
          list.forEach((v) => {
            const existing = byId.get(v.voucherId);
            // Không để phiếu 0đ cũ từ Cloud ghi đè lên phiếu đã cập nhật số tiền thực tế > 0 ở dưới máy
            if (existing && (Number(existing.amountVnd) || 0) > 0 && (Number(v.amountVnd) || 0) === 0) {
              byId.set(v.voucherId, existing);
            } else {
              byId.set(v.voucherId, v);
            }
          });
          const merged = Array.from(byId.values());
          merged.sort((a, b) => (b.createdAt?.toMillis?.() || 0) - (a.createdAt?.toMillis?.() || 0));
          try {
            localStorage.setItem(STORAGE_KEYS.VOUCHERS, JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {}
    );

    // Đồng bộ thời gian thực Danh bạ Khách hàng (customers) từ mọi tài khoản Nhân viên về Admin
    const custRealtimeQuery = query(collection(db, 'customers'), where('orgId', '==', ORG_ID));
    const unsubCustRealtime = onSnapshot(
      custRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        const deletedSet = deletedCustomerIdsRef.current;
        const list = snap.docs
          .map((d) => d.data() as Customer)
          .filter((c) => c && c.customerId && !deletedSet.has(c.customerId));
        if (list.length === 0) return;
        setCustomers((prev) => {
          const byId = new Map<string, Customer>();
          prev
            .filter((c) => !deletedSet.has(c.customerId))
            .forEach((c) => byId.set(c.customerId, c));
          list.forEach((c) => byId.set(c.customerId, c));
          const merged = Array.from(byId.values());
          try {
            localStorage.setItem(STORAGE_KEYS.CUSTOMERS, JSON.stringify(merged));
          } catch {
            // ignore
          }
          return merged;
        });
      },
      () => {}
    );

    // Đồng bộ thời gian thực Daily Report, Chi tiết thi công đơn hàng, Chi phí cố định, KPI & Duyệt xoá Khách hàng
    const wsRealtimeQuery = query(collection(db, 'workspace_sync'), where('orgId', '==', ORG_ID));
    const unsubWsRealtime = onSnapshot(
      wsRealtimeQuery,
      (snap) => {
        if (snap.empty) return;
        isApplyingRemoteWorkspaceSyncRef.current = true;
        try {
          snap.docs.forEach((d) => {
            const data = d.data() as Record<string, any>;
            if (!data) return;
            if (d.id === 'daily_reports') {
              if (Array.isArray(data.dailyReportLeads)) {
                setDailyReportLeads(data.dailyReportLeads as SaleDailyLeadReport[]);
              }
              if (data.dailyStaffExtraVideosMap && typeof data.dailyStaffExtraVideosMap === 'object') {
                setDailyStaffExtraVideosMap((prev) => ({
                  ...prev,
                  ...data.dailyStaffExtraVideosMap,
                }));
              }
            } else if (d.id === 'orders_and_details') {
              if (data.orderWorkDetailsMap && typeof data.orderWorkDetailsMap === 'object') {
                setOrderWorkDetailsMap(data.orderWorkDetailsMap);
              }
              if (Array.isArray(data.carBrands) && data.carBrands.length > 0) {
                setCarBrands((prev) => Array.from(new Set([...prev, ...data.carBrands])));
              }
              if (data.carModelsByBrand && typeof data.carModelsByBrand === 'object') {
                setCarModelsByBrand((prev) => ({ ...prev, ...data.carModelsByBrand }));
              }
              if (Array.isArray(data.mainTechniciansList) && data.mainTechniciansList.length > 0) {
                setMainTechniciansList((prev) => Array.from(new Set([...prev, ...data.mainTechniciansList])));
              }
              if (Array.isArray(data.subTechniciansList) && data.subTechniciansList.length > 0) {
                setSubTechniciansList((prev) => Array.from(new Set([...prev, ...data.subTechniciansList])));
              }
            } else if (d.id === 'finance_and_kpi') {
              if (Array.isArray(data.fixedExpenseItems) && data.fixedExpenseItems.length > 0) {
                setFixedExpenseItems(data.fixedExpenseItems);
              }
              if (data.fixedExpensesByMonthMap && typeof data.fixedExpensesByMonthMap === 'object') {
                setFixedExpensesByMonthMap((prev) => ({ ...prev, ...data.fixedExpensesByMonthMap }));
              }
              if (typeof data.openingCashVnd === 'number') {
                setOpeningCashVnd(data.openingCashVnd);
              }
              if (typeof data.openingBankVnd === 'number') {
                setOpeningBankVnd(data.openingBankVnd);
              }
              if (data.staffKpiByMonthMap && typeof data.staffKpiByMonthMap === 'object') {
                setStaffKpiByMonthMap((prev) => ({ ...prev, ...data.staffKpiByMonthMap }));
              }
            } else if (d.id === 'customers_sync') {
              if (Array.isArray(data.deletedCustomerIds)) {
                const remoteDeleted = data.deletedCustomerIds.filter(
                  (id: any) => typeof id === 'string'
                ) as string[];
                const mergedDel = Array.from(
                  new Set([...Array.from(deletedCustomerIdsRef.current), ...remoteDeleted])
                );
                deletedCustomerIdsRef.current = new Set(mergedDel);
                setDeletedCustomerIds(mergedDel);
                if (mergedDel.length > 0) {
                  const delSet = new Set(mergedDel);
                  setCustomers((prev) => {
                    const filtered = prev.filter((c) => !delSet.has(c.customerId));
                    if (filtered.length !== prev.length) {
                      try {
                        localStorage.setItem(STORAGE_KEYS.CUSTOMERS, JSON.stringify(filtered));
                      } catch {
                        // ignore
                      }
                    }
                    return filtered;
                  });
                }
              }
              if (data.pendingCustomerDeletes && typeof data.pendingCustomerDeletes === 'object') {
                setPendingCustomerDeletes(data.pendingCustomerDeletes);
              }
            }
          });
        } finally {
          setTimeout(() => {
            isApplyingRemoteWorkspaceSyncRef.current = false;
          }, 150);
        }
      },
      () => {}
    );

    return () => {
      unsubStaffPub();
      unsubProdRealtime();
      unsubSupRealtime();
      unsubOrdRealtime();
      unsubMovRealtime();
      unsubVchRealtime();
      unsubCustRealtime();
      unsubWsRealtime();
      window.removeEventListener('storage', handleStorageSync);
    };
  }, []);

  useEffect(() => {
    if (!authReady || !firebaseUser) return;

    const isBootAdmin =
      firebaseUser.email === BOOTSTRAPPED_ADMIN_EMAIL && firebaseUser.emailVerified;

    const staffPrivQuery = isBootAdmin
      ? query(collection(db, 'staff_private'), where('orgId', '==', ORG_ID))
      : query(
          collection(db, 'staff_private'),
          where('orgId', '==', ORG_ID),
          where('staffId', '==', firebaseUser.uid)
        );

    const unsubStaffPriv = onSnapshot(
      staffPrivQuery,
      (snap) => {
        if (!snap.empty) {
          setStaffPrivateMap((prev) => {
            const next = { ...prev };
            snap.docs.forEach((d) => {
              const info = d.data() as StaffPrivateInfo;
              if (!LEGACY_DEMO_IDS.staff.includes(info.staffId)) {
                next[info.staffId] = info;
              }
            });
            return next;
          });
        }
      },
      (err) => handleFirestoreError(err, OperationType.LIST, 'staff_private')
    );

    return () => {
      unsubStaffPriv();
    };
  }, [authReady, firebaseUser]);

  // Tự động chọn sản phẩm đầu tiên trong dropdown nếu kho có hàng
  useEffect(() => {
    if (products.length > 0) {
      if (!slipProductId || !products.some((p) => p.productId === slipProductId)) {
        setSlipProductId(products[0].productId);
      }
      if (!saleProductId || !products.some((p) => p.productId === saleProductId)) {
        setSaleProductId(products[0].productId);
      }
    } else {
      setSlipProductId('');
      setSaleProductId('');
    }
  }, [products, slipProductId, saleProductId]);

  // Đồng bộ tức thì toàn bộ dữ liệu từ tài khoản nhân viên lên Admin khi chuyển tab hoặc mở lại màn hình trên iOS / Android / Windows PC
  useEffect(() => {
    const syncStaffFromCloud = async () => {
      try {
        const snap = await getDocs(collection(db, 'staff_public'));
        if (!snap.empty) {
          const remoteList = snap.docs
            .map((d) => d.data() as StaffPublicProfile)
            .filter((s) => s && s.staffId && !LEGACY_DEMO_IDS.staff.includes(s.staffId));
          if (remoteList.length > 0) {
            setStaffPublic((prev) => {
              const byId = new Map<string, StaffPublicProfile>();
              prev.forEach((p) => byId.set(p.staffId, normalizeStaffProfilePermissions(p)));
              remoteList.forEach((p) => {
                const existing = byId.get(p.staffId);
                byId.set(
                  p.staffId,
                  normalizeStaffProfilePermissions({
                    ...(existing || {}),
                    ...p,
                  } as StaffPublicProfile)
                );
              });
              const merged = Array.from(byId.values());
              try {
                localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(merged));
              } catch {
                // ignore
              }
              return merged;
            });
          }
        }
      } catch {
        // ignore offline errors
      }
      try {
        const prodSnap = await getDocs(collection(db, 'products'));
        if (!prodSnap.empty) {
          const validDocs = prodSnap.docs
            .map((d) => d.data() as Product)
            .filter((p) => p && p.productId && !isLegacyOldWarehouseId(p.productId))
            .map((raw) =>
              sanitizeProductSellPrice({
                ...raw,
                supplier: normalizeSupplierShortName(raw.supplier),
                unit: normalizeProductUnit(raw),
              })
            );
          if (validDocs.length > 0) {
            setProducts((prev) => {
              const byId = new Map<string, Product>();
              prev
                .filter((p) => !isLegacyOldWarehouseId(p.productId))
                .forEach((p) => byId.set(p.productId, sanitizeProductSellPrice(p)));
              validDocs.forEach((p) => byId.set(p.productId, sanitizeProductSellPrice(p)));
              const mergedProds = Array.from(byId.values());
              try {
                localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(mergedProds));
              } catch {
                // ignore
              }
              return mergedProds;
            });
          }
        }
      } catch {
        // ignore offline errors
      }
      try {
        const ordSnap = await getDocs(collection(db, 'sales_orders'));
        if (!ordSnap.empty) {
          const list = ordSnap.docs
            .map((d) => d.data() as SalesOrder)
            .filter((o) => o && o.orderId && !LEGACY_DEMO_IDS.sales_orders.includes(o.orderId));
          if (list.length > 0) {
            setOrders((prev) => {
              const byId = new Map<string, SalesOrder>();
              prev.forEach((o) => byId.set(o.orderId, o));
              list.forEach((o) => byId.set(o.orderId, o));
              const merged = Array.from(byId.values());
              merged.sort((a, b) => (b.createdAt?.toMillis?.() || 0) - (a.createdAt?.toMillis?.() || 0));
              return merged;
            });
          }
        }
      } catch {
        // ignore
      }
      try {
        const wsSnap = await getDocs(collection(db, 'workspace_sync'));
        if (!wsSnap.empty) {
          isApplyingRemoteWorkspaceSyncRef.current = true;
          wsSnap.docs.forEach((d) => {
            const data = d.data() as Record<string, any>;
            if (!data) return;
            if (d.id === 'daily_reports') {
              if (Array.isArray(data.dailyReportLeads) && data.dailyReportLeads.length > 0) {
                setDailyReportLeads((prev) => {
                  const byId = new Map<string, SaleDailyLeadReport>();
                  prev.forEach((item) => byId.set(item.id, item));
                  (data.dailyReportLeads as SaleDailyLeadReport[]).forEach((item) => {
                    if (item && item.id) byId.set(item.id, item);
                  });
                  return Array.from(byId.values());
                });
              }
              if (data.dailyStaffExtraVideosMap && typeof data.dailyStaffExtraVideosMap === 'object') {
                setDailyStaffExtraVideosMap((prev) => ({
                  ...prev,
                  ...data.dailyStaffExtraVideosMap,
                }));
              }
            } else if (d.id === 'orders_and_details') {
              if (data.orderWorkDetailsMap && typeof data.orderWorkDetailsMap === 'object') {
                setOrderWorkDetailsMap((prev) => ({
                  ...prev,
                  ...data.orderWorkDetailsMap,
                }));
              }
            } else if (d.id === 'finance_and_kpi') {
              if (Array.isArray(data.fixedExpenseItems) && data.fixedExpenseItems.length > 0) {
                setFixedExpenseItems(data.fixedExpenseItems);
              }
              if (data.fixedExpensesByMonthMap && typeof data.fixedExpensesByMonthMap === 'object') {
                setFixedExpensesByMonthMap((prev) => ({ ...prev, ...data.fixedExpensesByMonthMap }));
              }
              if (typeof data.openingCashVnd === 'number') {
                setOpeningCashVnd(data.openingCashVnd);
              }
              if (typeof data.openingBankVnd === 'number') {
                setOpeningBankVnd(data.openingBankVnd);
              }
              if (data.staffKpiByMonthMap && typeof data.staffKpiByMonthMap === 'object') {
                setStaffKpiByMonthMap((prev) => ({ ...prev, ...data.staffKpiByMonthMap }));
              }
            } else if (d.id === 'customers_sync') {
              if (Array.isArray(data.deletedCustomerIds)) {
                const remoteDeleted = data.deletedCustomerIds.filter(
                  (id: any) => typeof id === 'string'
                ) as string[];
                const mergedDel = Array.from(
                  new Set([...Array.from(deletedCustomerIdsRef.current), ...remoteDeleted])
                );
                deletedCustomerIdsRef.current = new Set(mergedDel);
                setDeletedCustomerIds(mergedDel);
                if (mergedDel.length > 0) {
                  const delSet = new Set(mergedDel);
                  setCustomers((prev) => prev.filter((c) => !delSet.has(c.customerId)));
                }
              }
              if (data.pendingCustomerDeletes && typeof data.pendingCustomerDeletes === 'object') {
                setPendingCustomerDeletes(data.pendingCustomerDeletes);
              }
            }
          });
          setTimeout(() => {
            isApplyingRemoteWorkspaceSyncRef.current = false;
          }, 150);
        }
      } catch {
        // ignore
      }
    };

    const handleVisibilityOrFocus = () => {
      if (document.visibilityState === 'visible') {
        syncStaffFromCloud();
      }
    };

    window.addEventListener('focus', handleVisibilityOrFocus);
    document.addEventListener('visibilitychange', handleVisibilityOrFocus);
    return () => {
      window.removeEventListener('focus', handleVisibilityOrFocus);
      document.removeEventListener('visibilitychange', handleVisibilityOrFocus);
    };
  }, []);

  // Đồng bộ KPI tháng & Số ngày làm việc từ hồ sơ staff_public trên Cloud Firestore về bảng KPI
  useEffect(() => {
    if (!staffPublic || staffPublic.length === 0) return;
    const currentYm = new Date().toISOString().slice(0, 7);
    setStaffKpiByMonthMap((prev) => {
      let changed = false;
      const next = { ...prev };
      staffPublic.forEach((s) => {
        if (typeof s.monthlyKpiVnd === 'number' || typeof s.kpiWorkingDays === 'number') {
          const cleanName = (s.fullName || '')
            .replace(/\s*\(.*?\)\s*/g, '')
            .trim()
            .toLowerCase();
          const ym = s.kpiMonthStr && s.kpiMonthStr.length >= 7 ? s.kpiMonthStr.slice(0, 7) : currentYm;
          const key = `${ym}__${cleanName}`;
          const defaultKey = `default__${cleanName}`;
          const remoteKpi = typeof s.monthlyKpiVnd === 'number' ? s.monthlyKpiVnd : (next[key]?.monthlyKpiVnd ?? 0);
          const remoteDays = typeof s.kpiWorkingDays === 'number' && s.kpiWorkingDays >= 1 ? s.kpiWorkingDays : (next[key]?.workingDays ?? 26);
          if (!next[key] || next[key].monthlyKpiVnd !== remoteKpi || next[key].workingDays !== remoteDays) {
            next[key] = { monthlyKpiVnd: remoteKpi, workingDays: remoteDays };
            next[defaultKey] = { monthlyKpiVnd: remoteKpi, workingDays: remoteDays };
            changed = true;
          }
        }
      });
      return changed ? next : prev;
    });
  }, [staffPublic]);

  const currentAccount = useMemo(() => {
    if (activeStaffId) {
      const found = staffPublic.find((s) => s.staffId === activeStaffId);
      if (found) return normalizeStaffProfilePermissions(found);
    }
    return null;
  }, [activeStaffId, staffPublic]);

  const isLoggedIn = Boolean(currentAccount);

  // Tên nhân viên Sale tương ứng với tài khoản đang đăng nhập (nếu là tài khoản Sale)
  const loggedInSalePersonName = useMemo<string | null>(() => {
    if (!currentAccount) return null;
    const uname = (currentAccount.username || '').trim().toLowerCase();
    if (uname === 'quochuy') return 'Quốc Huy';
    if (uname === 'tranthinh') return 'Trần Thịnh';
    if (uname === 'nganthao') return 'Ngân Thảo';
    if (uname === 'ducminh') return 'Đức Minh';

    const cleanFull = (currentAccount.fullName || '')
      .replace(/\s*\(.*?\)\s*/g, '')
      .trim()
      .toLowerCase();
    if (cleanFull === 'quốc huy' || cleanFull === 'quoc huy') return 'Quốc Huy';
    if (cleanFull === 'trần thịnh' || cleanFull === 'tran thinh') return 'Trần Thịnh';
    if (cleanFull === 'ngân thảo' || cleanFull === 'ngan thao') return 'Ngân Thảo';
    if (cleanFull === 'đức minh' || cleanFull === 'duc minh') return 'Đức Minh';
    return null;
  }, [currentAccount]);

  const isAdminAccount = useMemo(() => {
    if (!currentAccount) return false;
    return (
      currentAccount.username?.toLowerCase() === 'admin' ||
      currentAccount.role === 'admin'
    );
  }, [currentAccount]);

  const effectivePermissions: StaffPermissions & { roleLabel: string; roleCode: StaffRole } = useMemo(() => {
    if (!currentAccount) {
      return {
        ...ROLE_DEFAULT_PERMISSIONS.cashier,
        roleLabel: 'Chưa đăng nhập',
        roleCode: 'cashier',
      };
    }
    if (isAdminAccount) {
      return {
        ...ROLE_DEFAULT_PERMISSIONS.admin,
        roleLabel: ROLE_LABELS[currentAccount.role],
        roleCode: currentAccount.role,
      };
    }
    const norm = normalizeStaffProfilePermissions(currentAccount);
    return {
      permDashboardView: norm.permDashboardView,
      permDailyReportView: norm.permDailyReportView,
      permSalesCreate: norm.permSalesCreate,
      permInventoryView: norm.permInventoryView,
      permCustomersView: norm.permCustomersView,
      permFinanceView: norm.permFinanceView,
      permCostPriceView: norm.permCostPriceView,
      permCustomerListView: norm.permCustomerListView,
      permSalesReportView: norm.permSalesReportView,
      permNetRevenueView: norm.permNetRevenueView,
      permGrossProfitView: norm.permGrossProfitView,
      permNetProfitView: norm.permNetProfitView,
      permSalesViewAll: Boolean(norm.permSalesViewAll),
      permDailyReportViewAll: Boolean(norm.permDailyReportViewAll),
      permSalesDiscountEdit: Boolean(norm.permSalesDiscountEdit ?? true),
      permCustomerPhoneView: Boolean(norm.permCustomerPhoneView ?? true),
      permCustomerEdit: Boolean(norm.permCustomerEdit ?? true),
      permFinanceCashbook: Boolean(norm.permFinanceCashbook),
      permFinanceFixedExpenses: Boolean(norm.permFinanceFixedExpenses),
      permInventoryImportExport: Boolean(norm.permInventoryImportExport),
      permInventoryEdit: norm.permInventoryEdit,
      permStockApprove: norm.permStockApprove,
      permSalesRefund: norm.permSalesRefund,
      permReportExport: norm.permReportExport,
      permStaffManage: norm.permStaffManage,
      roleLabel: ROLE_LABELS[currentAccount.role],
      roleCode: currentAccount.role,
    };
  }, [currentAccount, isAdminAccount]);

