  const getAccountPassword = (staffId: string, username: string): string => {
    const unameLower = (username || '').trim().toLowerCase();
    const staffItem =
      staffPublic.find((s) => s.staffId === staffId) ||
      staffPublic.find((s) => (s.username || '').trim().toLowerCase() === unameLower);
    const credItem =
      credentials.find((c) => c.staffId === staffId) ||
      credentials.find((c) => (c.username || '').trim().toLowerCase() === unameLower);
    const pw = (staffItem?.passwordPlain || credItem?.passwordPlain || '').trim();
    if ((unameLower === 'admin' || staffId === 'acc_admin_365md') && (!pw || pw === '123456')) {
      return 'admin123@';
    }
    if (pw.length >= 4) return pw;
    const def = DEFAULT_ACCOUNT_CREDENTIALS.find(
      (c) => c.staffId === staffId || c.username.toLowerCase() === unameLower
    );
    return def ? def.passwordPlain : unameLower === 'admin' ? 'admin123@' : '123456';
  };

  const handleCredentialLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const uClean = loginUsername.trim().toLowerCase();
    const pClean = loginPassword.trim();

    if (!uClean || !pClean) {
      notify('error', 'Vui lòng nhập đầy đủ ID đăng nhập và Mật khẩu.');
      return;
    }

    // Chỉ duy nhất nhân viên nhập đúng ID đăng nhập (username) và mật khẩu mới có thể đăng nhập
    const matchedProfile = staffPublic.find(
      (s) => (s.username || '').trim().toLowerCase() === uClean
    );

    if (!matchedProfile) {
      notify(
        'error',
        'ID đăng nhập hoặc mật khẩu không chính xác. Vui lòng kiểm tra lại thông tin đăng nhập.'
      );
      return;
    }

    if (matchedProfile.status !== 'active') {
      notify('error', 'Tài khoản này hiện đang bị tạm khóa hoặc ngừng hoạt động.');
      return;
    }

    const expectedPassword = getAccountPassword(matchedProfile.staffId, matchedProfile.username);
    const isPasswordValid = pClean === expectedPassword;

    if (!isPasswordValid) {
      notify(
        'error',
        'ID đăng nhập hoặc mật khẩu không chính xác. Vui lòng kiểm tra lại thông tin đăng nhập.'
      );
      return;
    }

    setActiveStaffId(matchedProfile.staffId);
    try {
      localStorage.removeItem('365md_auto_save_login_session');
      localStorage.removeItem(STORAGE_KEYS.SESSION_STAFF_ID);
    } catch {
      // ignore
    }
    setLoginUsername('');
    setLoginPassword('');
    setShowLoginPassword(false);
    setLoginInputsUnlocked(false);
    setShowSwitchAccountInDrawer(false);
    setShowMobileAccountDrawer(false);
    notify(
      'success',
      `Đăng nhập thành công vào hệ thống 365MD — Xin chào ${matchedProfile.fullName}.`
    );
  };

