  const handleSaveCustomer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!effectivePermissions.permSalesCreate && !effectivePermissions.permInventoryEdit) {
      notify(
        'error',
        'Từ chối truy cập: Tài khoản hiện tại cần quyền [Bán hàng/B2B] hoặc [Sửa Kho] để thêm/sửa khách hàng.'
      );
      return;
    }

    const nowTs = Timestamp.now();
    const creatorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
    const customerId = editingCustomer ? editingCustomer.customerId : `cust_365md_${Date.now()}`;
    const todayStr = new Intl.DateTimeFormat('vi-VN', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
    }).format(new Date());

    const payload: Customer = {
      customerId,
      orgId: ORG_ID,
      customerCode: sanitizeString(
        custCodeForm,
        VALIDATION_RULES.CUSTOMER_CODE_MAX_LEN,
        `KH-${Date.now().toString().slice(-4)}`
      ),
      name: sanitizeString(
        custNameForm,
        VALIDATION_RULES.CUSTOMER_NAME_MAX_LEN,
        'Khách hàng 365MD'
      ),
      phone: sanitizeString(
        custPhoneForm || 'Chưa cập nhật',
        VALIDATION_RULES.CUSTOMER_PHONE_MAX_LEN,
        'Chưa cập nhật'
      ),
      customerType: custTypeForm,
      vehicleOrGroup: sanitizeString(
        custVehicleForm || (custTypeForm === 'Khách ĐL / Gara' ? 'Khách ĐL' : 'VinFast VF3'),
        VALIDATION_RULES.CUSTOMER_VEHICLE_MAX_LEN,
        'VinFast VF3'
      ),
      address: sanitizeString(
        custAddressForm || 'Chưa cập nhật',
        VALIDATION_RULES.CUSTOMER_ADDR_MAX_LEN,
        'Chưa cập nhật'
      ),
      note: sanitizeString(
        custNoteForm || `Nhóm/Xe: ${custVehicleForm || 'Khách hàng 365MD'}`,
        VALIDATION_RULES.CUSTOMER_NOTE_MAX_LEN,
        'Khách hàng 365MD'
      ),
      branch: editingCustomer ? editingCustomer.branch : 'Chi nhánh trung tâm',
      createdDateStr: editingCustomer ? editingCustomer.createdDateStr : todayStr,
      lastTransactionDateStr: todayStr,
      createdBy: editingCustomer ? editingCustomer.createdBy : creatorUid,
      createdAt: editingCustomer ? editingCustomer.createdAt : nowTs,
      updatedAt: nowTs,
    };

    if (editingCustomer) {
      setCustomers((prev) => {
        const next = prev.map((c) => (c.customerId === editingCustomer.customerId ? payload : c));
        try {
          localStorage.setItem(STORAGE_KEYS.CUSTOMERS, JSON.stringify(next));
        } catch {
          // ignore
        }
        return next;
      });
    } else {
      setCustomers((prev) => {
        const next = [payload, ...prev];
        try {
          localStorage.setItem(STORAGE_KEYS.CUSTOMERS, JSON.stringify(next));
        } catch {
          // ignore
        }
        return next;
      });
    }

    try {
      await setDoc(doc(db, 'customers', customerId), {
        ...payload,
        createdBy: creatorUid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
    } catch {
      // Local state already updated
    }

    notify(
      'success',
      editingCustomer
        ? `Đã cập nhật thông tin khách hàng [${payload.name} — ${payload.customerCode}].`
        : `Đã thêm khách hàng mới [${payload.name} — ${payload.customerCode}] vào danh bạ 365MD.`
    );
    setShowCustomerModal(false);
  };

  const handleSelectCustomerForPos = (c: Customer) => {
    setSaleSelectedCustomerId(c.customerId);
    setSaleCustomerName(c.name);
    setSaleCustomerPhone(c.phone && c.phone !== 'Chưa cập nhật' ? c.phone : '');
    setSaleCustomerAddress(c.address && c.address !== 'Chưa cập nhật' ? c.address : '');
    const isPlateCode = !c.customerCode.toUpperCase().startsWith('KH');
    setSaleLicensePlate(isPlateCode ? c.customerCode : '');

    // Tự động tách Hãng xe & Dòng xe từ thông tin khách hàng KiotViet
    const vg = (c.vehicleOrGroup || '').trim();
    const matchedBrand = carBrands.find((b) => vg.toLowerCase().includes(b.toLowerCase()));
    if (matchedBrand) {
      setSaleCarBrand(matchedBrand);
      const modelPart = vg.replace(new RegExp(matchedBrand, 'i'), '').trim();
      setSaleCarModel(modelPart || vg);
    } else if (vg && vg !== 'Chưa cập nhật dòng xe') {
      setSaleCarModel(vg);
    }

    const refParts = [
      c.customerCode,
      c.phone && c.phone !== 'Chưa cập nhật' ? c.phone : '',
    ].filter(Boolean);
    setSaleCustomerRef(refParts.join(' - ').slice(0, VALIDATION_RULES.CUSTOMER_REF_MAX_LEN));
    if (c.customerType === 'Khách ĐL / Gara') {
      setSaleChannel('Phân phối Đại lý & Gara Đối tác (B2B)');
    } else {
      setSaleChannel('Dịch vụ Lắp đặt Trực tiếp tại Xưởng');
    }
    setActiveSection('sales');
    setShowCreateOrderForm(true);
    notify(
      'info',
      `Đã điền khách hàng [${c.name} — ${c.customerCode}] vào phiếu Tạo đơn mới.`
    );
  };

  const handleSelectCustomerForVoucher = (c: Customer) => {
    if (!canAccessFinanceTab) {
      notify('error', 'Tài khoản hiện tại không có quyền truy cập mục Quản lý Tài chính.');
      return;
    }
    setVoucherTypeForm('receipt');
    setVoucherCategoryForm('Thu công nợ Khách hàng / Đại lý');
    setVoucherTargetNameForm(`${c.name} (${c.customerCode})`);
    setVoucherRefCodeForm(c.customerCode);
    setVoucherDescForm(
      `Thu tiền từ khách hàng ${c.name} (${c.vehicleOrGroup}) — SĐT: ${c.phone}`
    );
    setActiveSection('finance');
    notify(
      'info',
      `Đã điền thông tin khách hàng [${c.name}] vào Phiếu Thu tiền tại Sổ quỹ.`
    );
  };

  // =========================================================================
  // KIOTVIET EXCEL / CSV / PASTE IMPORT HANDLERS
  // =========================================================================
  const processKiotVietRows = (rows: Array<Record<string, unknown>>, sourceLabel: string) => {
    const creatorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
    const cashierName = currentAccount?.fullName || 'Quản trị viên 365MD';

    if (rows.length === 0) {
      notify(
        'error',
        'Không tìm thấy dòng dữ liệu hợp lệ trong file/bảng vừa chọn. Vui lòng kiểm tra dòng tiêu đề cột.'
      );
      return;
    }

    if (kiotImportMode === 'products') {
      const res = parseKiotVietProductsFromRows(rows, creatorUid);
      setKiotPreviewProducts(res.products);
      setKiotPreviewOrders([]);
      setKiotPreviewCustomers([]);
      setKiotDetectedCols(res.detectedColumns);
      setKiotFileName(sourceLabel);
      notify(
        'info',
        `Đã đọc thành công ${res.products.length} mặt hàng từ [${sourceLabel}]. Vui lòng kiểm tra bảng xem trước và nhấn "Xác nhận Đồng bộ vào 365MD".`
      );
    } else if (kiotImportMode === 'customers') {
      const res = parseKiotVietCustomersFromRows(rows, creatorUid);
      setKiotPreviewCustomers(res.customers);
      setKiotPreviewProducts([]);
      setKiotPreviewOrders([]);
      setKiotDetectedCols(res.detectedColumns);
      setKiotFileName(sourceLabel);
      notify(
        'info',
        `Đã đọc thành công ${res.customers.length} khách hàng từ [${sourceLabel}]. Vui lòng kiểm tra bảng xem trước và nhấn "Xác nhận Đồng bộ vào 365MD".`
      );
    } else {
      const res = parseKiotVietOrdersFromRows(rows, creatorUid, cashierName, products);
      setKiotPreviewOrders(res.orders);
      setKiotPreviewProducts([]);
      setKiotPreviewCustomers([]);
      setKiotDetectedCols(res.detectedColumns);
      setKiotFileName(sourceLabel);
      notify(
        'info',
        `Đã đọc thành công ${res.orders.length} hóa đơn bán hàng từ [${sourceLabel}]. Vui lòng kiểm tra bảng xem trước và nhấn "Xác nhận Đồng bộ vào 365MD".`
      );
    }
  };

  const handleKiotFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const rows = await readExcelOrCsvFileToRows(file);
      processKiotVietRows(rows, file.name);
    } catch (error) {
      notify(
        'error',
        error instanceof Error
          ? `Không thể đọc file Excel/CSV: ${error.message}`
          : 'Lỗi định dạng file Excel/CSV.'
      );
    } finally {
      e.target.value = '';
    }
  };

  const handleKiotPasteParse = () => {
    if (!kiotPasteText.trim()) {
      notify('error', 'Vui lòng dán dữ liệu copy từ bảng Excel / Google Sheets.');
      return;
    }
    try {
      const rows = parsePastedSpreadsheetTextToRows(kiotPasteText);
      processKiotVietRows(rows, 'Dữ liệu dán từ Bảng tính');
    } catch {
      notify('error', 'Không thể phân tích dữ liệu vừa dán. Hãy đảm bảo có dòng tiêu đề cột ở dòng đầu tiên.');
    }
  };

  const handleConfirmKiotImport = async () => {
    if (kiotImportMode === 'products') {
      if (!effectivePermissions.permInventoryEdit) {
        notify('error', 'Tài khoản hiện tại cần quyền [Sửa Kho] để nhập hàng hóa.');
        return;
      }
      if (kiotPreviewProducts.length === 0) {
        notify('error', 'Chưa có sản phẩm nào trong danh sách chờ đồng bộ.');
        return;
      }

      setIsImportingKiot(true);
      try {
        setProducts((prev) => {
          if (kiotMergeStrategy === 'replace') {
            return kiotPreviewProducts;
          }
          // Merge by SKU (update existing SKU or append new SKU)
          const mapBySku = new Map<string, Product>();
          prev.forEach((p) => mapBySku.set(p.sku.toUpperCase(), p));
          kiotPreviewProducts.forEach((incoming) => {
            const existing = mapBySku.get(incoming.sku.toUpperCase());
            if (existing) {
              mapBySku.set(incoming.sku.toUpperCase(), {
                ...incoming,
                productId: existing.productId,
              });
            } else {
              mapBySku.set(incoming.sku.toUpperCase(), incoming);
            }
          });
          return Array.from(mapBySku.values());
        });

        const importActorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
        for (const p of kiotPreviewProducts) {
          try {
            await setDoc(doc(db, 'products', p.productId), {
              ...p,
              createdBy: importActorUid,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
            });
          } catch {
            // Local state already updated
          }
        }

        notify(
          'success',
          `Đã đồng bộ thành công ${kiotPreviewProducts.length} mã hàng hóa & tồn kho vào hệ thống 365MD!`
        );
        setKiotPreviewProducts([]);
        setKiotPasteText('');
        setShowKiotVietModal(false);
        setActiveSection('inventory');
      } finally {
        setIsImportingKiot(false);
      }
    } else if (kiotImportMode === 'customers') {
      if (!effectivePermissions.permSalesCreate && !effectivePermissions.permInventoryEdit) {
        notify('error', 'Tài khoản hiện tại cần quyền [Bán hàng/B2B] để nhập danh sách khách hàng.');
        return;
      }
      if (kiotPreviewCustomers.length === 0) {
        notify('error', 'Chưa có khách hàng nào trong danh sách chờ đồng bộ.');
        return;
      }

      setIsImportingKiot(true);
      try {
        setCustomers((prev) => {
          if (kiotMergeStrategy === 'replace') {
            return kiotPreviewCustomers;
          }
          const mapByCode = new Map<string, Customer>();
          prev.forEach((c) => mapByCode.set(c.customerCode.toUpperCase(), c));
          kiotPreviewCustomers.forEach((incoming) => {
            const existing = mapByCode.get(incoming.customerCode.toUpperCase());
            if (existing) {
              mapByCode.set(incoming.customerCode.toUpperCase(), {
                ...incoming,
                customerId: existing.customerId,
              });
            } else {
              mapByCode.set(incoming.customerCode.toUpperCase(), incoming);
            }
          });
          return Array.from(mapByCode.values());
        });

        const importCustActorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
        for (const c of kiotPreviewCustomers.slice(0, 100)) {
          try {
            await setDoc(doc(db, 'customers', c.customerId), {
              ...c,
              createdBy: importCustActorUid,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
            });
          } catch {
            // Local state already updated
          }
        }

        notify(
          'success',
          `Đã đồng bộ thành công ${kiotPreviewCustomers.length} khách hàng vào hệ thống 365MD!`
        );
        setKiotPreviewCustomers([]);
        setKiotPasteText('');
        setShowKiotVietModal(false);
        setActiveSection('customers');
      } finally {
        setIsImportingKiot(false);
      }
    } else {
      if (!effectivePermissions.permSalesCreate) {
        notify('error', 'Tài khoản hiện tại cần quyền [Bán hàng/B2B] để nhập hóa đơn bán hàng.');
        return;
      }
      if (kiotPreviewOrders.length === 0) {
        notify('error', 'Chưa có hóa đơn nào trong danh sách chờ đồng bộ.');
        return;
      }

      setIsImportingKiot(true);
      try {
        setOrders((prev) => {
          if (kiotMergeStrategy === 'replace') {
            return kiotPreviewOrders;
          }
          const mapByInv = new Map<string, SalesOrder>();
          prev.forEach((o) => mapByInv.set(o.invoiceNumber.toUpperCase(), o));
          kiotPreviewOrders.forEach((incoming) => {
            const existing = mapByInv.get(incoming.invoiceNumber.toUpperCase());
            if (existing) {
              mapByInv.set(incoming.invoiceNumber.toUpperCase(), {
                ...incoming,
                orderId: existing.orderId,
              });
            } else {
              mapByInv.set(incoming.invoiceNumber.toUpperCase(), incoming);
            }
          });
          return Array.from(mapByInv.values());
        });

        const importOrdActorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
        for (const o of kiotPreviewOrders) {
          try {
            await setDoc(doc(db, 'sales_orders', o.orderId), {
              ...o,
              cashierId: importOrdActorUid,
              createdAt: serverTimestamp(),
              updatedAt: serverTimestamp(),
            });
          } catch {
            // Local state already updated
          }
        }

        notify(
          'success',
          `Đã đồng bộ thành công ${kiotPreviewOrders.length} hóa đơn bán hàng vào hệ thống 365MD!`
        );
        setKiotPreviewOrders([]);
        setKiotPasteText('');
        setShowKiotVietModal(false);
        setActiveSection('sales');
      } finally {
        setIsImportingKiot(false);
      }
    }
  };

  // =========================================================================
  // ACCOUNT & DIRECT PERMISSION MANAGEMENT HANDLERS (ADMIN)
  // =========================================================================
  const openCreateAccountModal = () => {
    const nextIdx = staffPublic.length + 1;
    setNewAccUsername('');
    setNewAccPassword('');
    setNewStaffName('');
    setNewStaffCode(`NV-${String(nextIdx).padStart(3, '0')}`);
    setNewStaffRole('sales_lead');
    setNewStaffDept('Kinh Doanh POS');
    setNewStaffBranch('Auto365 Mỹ Đình - Hà Nội');
    setNewStaffEmail('');
    setNewStaffPhone('');
    setNewStaffSalary(0);
    setNewStaffContract('Toàn thời gian');
    setNewStaffPerms({ ...ROLE_DEFAULT_PERMISSIONS.sales_lead });
    setShowNewStaffModal(true);
  };

  const handleRolePresetChangeInModal = (role: StaffRole) => {
    setNewStaffRole(role);
    setNewStaffPerms({ ...ROLE_DEFAULT_PERMISSIONS[role] });
    if (role === 'warehouse_manager') setNewStaffDept('Kho Vận');
    else if (role === 'sales_lead' || role === 'cashier') setNewStaffDept('Kinh Doanh POS');
    else if (role === 'auditor') setNewStaffDept('Kế Toán & Kiểm Toán');
    else if (role === 'admin') setNewStaffDept('Ban Giám Đốc');
  };

  const handleCreateAccountSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!effectivePermissions.permStaffManage) {
      notify(
        'error',
        'Từ chối truy cập: Tài khoản hiện tại không có quyền [Quản trị Account] để tạo tài khoản mới.'
      );
      return;
    }

    const cleanUsername = sanitizeUsername(newAccUsername);
    if (
      staffPublic.some((s) => s.username.toLowerCase() === cleanUsername.toLowerCase())
    ) {
      notify('error', `Tên đăng nhập "${cleanUsername}" đã tồn tại. Vui lòng chọn tên đăng nhập khác.`);
      return;
    }

    const cleanPassword = newAccPassword.trim() || '123456';
    if (cleanPassword.length < 4) {
      notify('error', 'Mật khẩu tài khoản phải có ít nhất 4 ký tự.');
      return;
    }

    const staffId = `staff_365md_${Date.now()}`;
    const cleanCode = VALIDATION_RULES.EMP_CODE_REGEX.test(newStaffCode.trim())
      ? newStaffCode.trim()
      : `NV-${String(staffPublic.length + 1).padStart(3, '0')}`;
    const nowTs = Timestamp.now();
    const creatorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';

    const newPub: StaffPublicProfile = {
      staffId,
      orgId: ORG_ID,
      username: cleanUsername,
      passwordPlain: cleanPassword,
      fullName: sanitizeString(newStaffName, VALIDATION_RULES.FULL_NAME_MAX_LEN, `Nhân viên ${cleanUsername}`),
      employeeCode: cleanCode,
      role: newStaffRole,
      department: newStaffDept,
      branch: sanitizeString(newStaffBranch, VALIDATION_RULES.BRANCH_MAX_LEN, 'Auto365 Mỹ Đình - Hà Nội'),
      status: 'active',
      ...newStaffPerms,
      createdBy: creatorUid,
      createdAt: nowTs,
      updatedAt: nowTs,
    };

    const newPriv: StaffPrivateInfo = {
      staffId,
      orgId: ORG_ID,
      email: sanitizeString(newStaffEmail || `${cleanUsername}@auto365mydinh.vn`, VALIDATION_RULES.EMAIL_MAX_LEN),
      phone: sanitizeString(newStaffPhone, VALIDATION_RULES.PHONE_MAX_LEN, '0909365365'),
      baseSalaryVnd: Math.max(0, Math.min(500000000, Math.round(Number(newStaffSalary) || 0))),
      contractType: newStaffContract,
      createdBy: creatorUid,
      createdAt: nowTs,
      updatedAt: nowTs,
    };

    setStaffPublic((prev) => [...prev, newPub]);
    setStaffPrivateMap((prev) => ({ ...prev, [staffId]: newPriv }));
    setCredentials((prev) => [
      ...prev.filter((c) => c.staffId !== staffId && c.username !== cleanUsername),
      { staffId, username: cleanUsername, passwordPlain: cleanPassword },
    ]);

    try {
      await setDoc(
        doc(db, 'staff_public', staffId),
        serializeStaffPublicForFirestore(newPub),
        { merge: true }
      );
      if (firebaseUser) {
        await setDoc(doc(db, 'staff_private', staffId), {
          ...newPriv,
          createdBy: firebaseUser.uid,
          createdAt: serverTimestamp(),
          updatedAt: serverTimestamp(),
        });
      }
    } catch {
      // Local state updated
    }

    notify(
      'success',
      `Đã tạo tài khoản mới thành công! Tên đăng nhập: [${cleanUsername}] · Mật khẩu: [${cleanPassword}].`
    );
    setShowNewStaffModal(false);
  };

  const handleToggleAccountPermission = async (
    staff: StaffPublicProfile,
    permKey: keyof StaffPermissions
  ) => {
    if (!effectivePermissions.permStaffManage) {
      notify(
        'error',
        'Từ chối truy cập: Chỉ tài khoản Admin hoặc có quyền [Quản trị Account] mới được thay đổi phân quyền.'
      );
      return;
    }

    if (staff.username === 'admin') {
      notify('error', 'Tài khoản gốc [admin] luôn được BẬT toàn bộ quyền quản trị hệ thống.');
      return;
    }

    const normStaff = normalizeStaffProfilePermissions(staff);
    const nextVal = !normStaff[permKey];
    const nowTs = Timestamp.now();

    // Khi Admin BẬT quyền [Quản lý Tài chính] (permFinanceView), tự động bật Sổ quỹ & Chi phí cố định nếu cả 2 đang tắt
    const extraFinancePerms: Partial<StaffPermissions> =
      permKey === 'permFinanceView' && nextVal && !normStaff.permFinanceCashbook && !normStaff.permFinanceFixedExpenses
        ? { permFinanceCashbook: true, permFinanceFixedExpenses: true }
        : {};

    const updatedProfile = normalizeStaffProfilePermissions({
      ...normStaff,
      ...extraFinancePerms,
      [permKey]: nextVal,
      updatedAt: nowTs,
    });

    setStaffPublic((prev) => {
      const nextList = prev.map((item) =>
        item.staffId === staff.staffId ? updatedProfile : item
      );
      try {
        localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });

    try {
      await setDoc(
        doc(db, 'staff_public', staff.staffId),
        serializeStaffPublicForFirestore(updatedProfile),
        { merge: true }
      );
    } catch {
      // Local state updated
    }

    setHasUnsavedRbacChanges(true);
    const permLabel = PERMISSION_METADATA.find((m) => m.key === permKey)?.title || permKey;
    notify(
      'success',
      `Đã ${nextVal ? 'BẬT' : 'TẮT'} quyền [${permLabel}] cho tài khoản [${staff.username}]. Nhấn nút "SAVE" ở cuối bảng để lưu chốt toàn bộ phân quyền.`
    );
  };

  const handleBulkSetAccountPermissions = async (
    staff: StaffPublicProfile,
    presetOrPerms:
      | 'ALL_ON'
      | 'SALE_STANDARD'
      | 'WAREHOUSE_ONLY'
      | 'ALL_OFF'
      | Partial<StaffPermissions>,
    customLabel?: string
  ) => {
    if (!effectivePermissions.permStaffManage) {
      notify('error', 'Từ chối truy cập: Chỉ Admin mới được thay đổi phân quyền.');
      return;
    }
    if (staff.username === 'admin') {
      notify('error', 'Tài khoản gốc [admin] luôn giữ toàn quyền (Full Admin).');
      return;
    }

    let nextPerms: StaffPermissions;
    let label = customLabel || '';
    if (typeof presetOrPerms === 'object' && presetOrPerms !== null) {
      nextPerms = {
        ...ROLE_DEFAULT_PERMISSIONS.sales_lead,
        ...presetOrPerms,
      };
      if (!label) label = 'Cấu hình Tùy chỉnh';
    } else if (presetOrPerms === 'ALL_ON') {
      nextPerms = {
        ...ROLE_DEFAULT_PERMISSIONS.admin,
        permStaffManage: false,
      };
      label = label || 'BẬT TẤT CẢ QUYỀN';
    } else if (presetOrPerms === 'SALE_STANDARD') {
      nextPerms = {
        ...ROLE_DEFAULT_PERMISSIONS.sales_lead,
      };
      label = label || 'CHUẨN SALE (Ẩn Tài chính, Giá vốn & Lãi)';
    } else if (presetOrPerms === 'WAREHOUSE_ONLY') {
      nextPerms = {
        ...ROLE_DEFAULT_PERMISSIONS.warehouse_manager,
      };
      label = label || 'CHUẨN KHO HÀNG';
    } else {
      nextPerms = {
        permDashboardView: true,
        permDailyReportView: false,
        permSalesCreate: false,
        permInventoryView: false,
        permCustomersView: false,
        permFinanceView: false,
        permCostPriceView: false,
        permCustomerListView: false,
        permSalesReportView: false,
        permNetRevenueView: false,
        permGrossProfitView: false,
        permNetProfitView: false,
        permSalesViewAll: false,
        permDailyReportViewAll: false,
        permSalesDiscountEdit: false,
        permCustomerPhoneView: false,
        permCustomerEdit: false,
        permFinanceCashbook: false,
        permFinanceFixedExpenses: false,
        permInventoryImportExport: false,
        permInventoryEdit: false,
        permStockApprove: false,
        permSalesRefund: false,
        permReportExport: false,
        permStaffManage: false,
      };
      label = label || 'TẮT TẤT CẢ QUYỀN (Chỉ xem khung Tổng quan)';
    }

    const nowTs = Timestamp.now();
    const updatedProfile = normalizeStaffProfilePermissions({
      ...staff,
      ...nextPerms,
      updatedAt: nowTs,
    });

    setStaffPublic((prev) => {
      const nextList = prev.map((item) =>
        item.staffId === staff.staffId ? updatedProfile : item
      );
      try {
        localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });

    try {
      await setDoc(
        doc(db, 'staff_public', staff.staffId),
        serializeStaffPublicForFirestore(updatedProfile),
        { merge: true }
      );
    } catch {
      // Local state updated
    }

    setHasUnsavedRbacChanges(true);
    notify('success', `Đã áp dụng cấu hình [${label}] cho tài khoản [${staff.username}]. Nhấn nút "SAVE" ở cuối bảng để lưu chốt phân quyền.`);
  };

  const handleUpdateAccountRoleOrStatus = async (
    staff: StaffPublicProfile,
    nextRole: StaffRole,
    nextStatus: StaffStatus
  ) => {
    if (!effectivePermissions.permStaffManage) {
      notify('error', 'Từ chối truy cập: Bạn không có quyền [Quản trị Account].');
      return;
    }
    if (staff.username === 'admin' && (nextRole !== 'admin' || nextStatus !== 'active')) {
      notify('error', 'Tài khoản gốc [admin] luôn giữ vai trò Giám đốc (Full Admin) và trạng thái Hoạt động.');
      return;
    }

    const presetPerms = ROLE_DEFAULT_PERMISSIONS[nextRole];
    const nowTs = Timestamp.now();
    const updatedProfile = normalizeStaffProfilePermissions({
      ...staff,
      role: nextRole,
      status: nextStatus,
      ...presetPerms,
      updatedAt: nowTs,
    });

    setStaffPublic((prev) => {
      const nextList = prev.map((item) =>
        item.staffId === staff.staffId ? updatedProfile : item
      );
      try {
        localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });

    try {
      await setDoc(
        doc(db, 'staff_public', staff.staffId),
        serializeStaffPublicForFirestore(updatedProfile),
        { merge: true }
      );
    } catch {
      // Local state updated
    }

    setHasUnsavedRbacChanges(true);
    notify(
      'success',
      `Đã cập nhật account [${staff.username}] sang vai trò [${ROLE_LABELS[nextRole]}]. Nhấn nút "SAVE" ở cuối bảng để lưu chốt phân quyền.`
    );
  };

  // Nút SAVE ở cuối bảng Phân quyền Admin: Lưu chốt & đồng bộ toàn bộ bảng phân quyền lên Cloud Firestore + LocalStorage
  const handleSaveAllPermissionsTable = async () => {
    if (!isAdminAccount && !effectivePermissions.permStaffManage) {
      notify('error', 'Từ chối truy cập: Chỉ tài khoản Admin mới có quyền lưu bảng phân quyền.');
      return;
    }
    setIsSavingAllPermissions(true);
    const nowTs = Timestamp.now();
    const normalizedAll = staffPublic.map((acc) => {
      const pw = getAccountPassword(acc.staffId, acc.username);
      return {
        ...normalizeStaffProfilePermissions(acc),
        passwordPlain: pw,
        updatedAt: nowTs,
      };
    });

    setStaffPublic(normalizedAll);
    try {
      localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(normalizedAll));
      const updatedCreds = normalizedAll.map((acc) => ({
        staffId: acc.staffId,
        username: acc.username,
        passwordPlain: acc.passwordPlain || getAccountPassword(acc.staffId, acc.username),
      }));
      localStorage.setItem(STORAGE_KEYS.CREDENTIALS, JSON.stringify(updatedCreds));
    } catch {
      // ignore
    }

    try {
      await Promise.all(
        normalizedAll.map((acc) =>
          setDoc(
            doc(db, 'staff_public', acc.staffId),
            serializeStaffPublicForFirestore(acc, acc.passwordPlain),
            { merge: true }
          )
        )
      );
    } catch {
      // Local state already persisted
    }

    const timeStr = new Date().toLocaleTimeString('vi-VN', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    }) + ' - ' + new Date().toLocaleDateString('vi-VN');

    setLastSavedRbacTimeStr(timeStr);
    setHasUnsavedRbacChanges(false);
    setIsSavingAllPermissions(false);
    try {
      localStorage.setItem('365md_last_saved_rbac_time', timeStr);
    } catch {
      // ignore
    }

    notify(
      'success',
      `ĐÃ LƯU (SAVE) THÀNH CÔNG! Toàn bộ phân quyền mới của ${normalizedAll.length} tài khoản đã được lưu và đồng bộ trên mọi Máy tính Windows, iOS & Android (lúc ${timeStr}).`
    );
  };

  const handleSaveNewPassword = async (staff: StaffPublicProfile, overridePassword?: string) => {
    if (!isAdminAccount && !effectivePermissions.permStaffManage) {
      notify('error', 'Từ chối truy cập: Chỉ tài khoản Admin mới có quyền thay đổi mật khẩu cho các tài khoản.');
      return;
    }
    const clean = (overridePassword !== undefined ? overridePassword : tempNewPassword).trim();
    if (clean.length < 4) {
      notify('error', 'Mật khẩu mới phải có ít nhất 4 ký tự.');
      return;
    }
    if (clean.length > 64) {
      notify('error', 'Mật khẩu không được vượt quá 64 ký tự.');
      return;
    }

    const nowTs = Timestamp.now();
    const updatedProfile: StaffPublicProfile = {
      ...normalizeStaffProfilePermissions(staff),
      passwordPlain: clean,
      updatedAt: nowTs,
    };

    setStaffPublic((prev) => {
      const nextList = prev.map((item) =>
        item.staffId === staff.staffId ? updatedProfile : item
      );
      try {
        localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });

    setCredentials((prev) => {
      const nextCreds = [
        ...prev.filter((c) => c.staffId !== staff.staffId && c.username.toLowerCase() !== staff.username.toLowerCase()),
        { staffId: staff.staffId, username: staff.username, passwordPlain: clean },
      ];
      try {
        localStorage.setItem(STORAGE_KEYS.CREDENTIALS, JSON.stringify(nextCreds));
      } catch {
        // ignore
      }
      return nextCreds;
    });

    setEditingPasswordStaffId(null);
    setTempNewPassword('');

    try {
      await setDoc(
        doc(db, 'staff_public', staff.staffId),
        serializeStaffPublicForFirestore(updatedProfile, clean),
        { merge: true }
      );
    } catch {
      // Local state updated
    }

    notify(
      'success',
      `Đã đổi mật khẩu thành công cho tài khoản [${staff.username}] (${staff.fullName}) sang [${clean}] — Đã đồng bộ ngay trên cả Mobile & PC!`
    );
  };

  const handleDeleteAccount = async (staff: StaffPublicProfile) => {
    if (!effectivePermissions.permStaffManage) {
      notify('error', 'Từ chối truy cập: Bạn không có quyền xóa tài khoản.');
      return;
    }
    if (staff.username === 'admin') {
      notify('error', 'Không thể xóa tài khoản quản trị viên gốc [admin].');
      return;
    }
    setStaffPublic((prev) => {
      const nextList = prev.filter((s) => s.staffId !== staff.staffId);
      try {
        localStorage.setItem(STORAGE_KEYS.STAFF_PUB, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });
    setCredentials((prev) => prev.filter((c) => c.staffId !== staff.staffId));
    if (activeStaffId === staff.staffId) {
      setActiveStaffId('acc_admin_365md');
    }
    try {
      await deleteDoc(doc(db, 'staff_public', staff.staffId));
      if (firebaseUser) {
        await deleteDoc(doc(db, 'staff_private', staff.staffId));
      }
    } catch {
      // ignore
    }
    notify('info', `Đã xóa tài khoản [${staff.username}] (${staff.fullName}) khỏi hệ thống.`);
  };

  // =========================================================================
  // INVENTORY & STOCK MOVEMENT HANDLERS
  // =========================================================================
  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!effectivePermissions.permInventoryEdit) {
      notify(
        'error',
        'Từ chối truy cập: Tài khoản hiện tại không được cấp quyền [Sửa Kho] (permInventoryEdit).'
      );
      return;
    }

    const cleanSku = prodSku.trim()
      ? sanitizeString(prodSku.trim().toUpperCase(), VALIDATION_RULES.SKU_MAX_LEN, '')
      : '';
    const cleanName = sanitizeString(prodName, VALIDATION_RULES.PRODUCT_NAME_MAX_LEN, 'Sản phẩm 365MD');

    // Nếu người dùng có gõ Tên nhà cung cấp mới trong ô Thêm nhà cung cấp thì tự động lưu vào Danh mục NCC
    let effectiveSupplierRaw = prodSupplier;
    if (newSupplierNameInput.trim()) {
      effectiveSupplierRaw = newSupplierNameInput.trim();
      handleSaveSupplierToCatalog(newSupplierNameInput.trim(), newSupplierPhoneInput.trim());
    }

    const cleanSupplier = effectiveSupplierRaw.trim()
      ? sanitizeString(
          normalizeSupplierShortName(effectiveSupplierRaw),
          VALIDATION_RULES.SUPPLIER_MAX_LEN,
          ''
        )
      : '';
    const cleanBatch = sanitizeString(prodBatch, VALIDATION_RULES.BATCH_MAX_LEN, '27/10/2026');
    const safeCost = Math.max(0, Math.min(10000000000, Number(prodCost) || 0));
    const safeSell = Math.max(0, Math.min(10000000000, Number(prodSell) || 0));
    const safeStock = Math.max(-100000, Math.min(1000000, Number(prodStock) || 0));
    const safeMin = Math.max(0, Math.min(100000, Math.round(Number(prodMinThreshold) || 0)));
    const computedStatus = computeProductStatus(safeStock, safeMin);

    const parsedDate = prodInboundDate ? new Date(`${prodInboundDate}T09:00:00`) : new Date();
    const nowTs = !Number.isNaN(parsedDate.getTime())
      ? Timestamp.fromDate(parsedDate)
      : Timestamp.now();
    const creatorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
    const creatorName = sanitizeString(
      currentAccount?.fullName || 'Quản trị viên 365MD',
      VALIDATION_RULES.FULL_NAME_MAX_LEN
    );

    if (editingProduct) {
      const stockDelta = safeStock - editingProduct.stockQty;
      const updatedProd: Product = {
        ...editingProduct,
        sku: cleanSku,
        name: cleanName,
        supplier: cleanSupplier,
        category: prodCategory,
        unit: prodUnit,
        warehouseZone: prodZone,
        batchNumber: cleanBatch,
        costPriceVnd: safeCost,
        sellPriceVnd: safeSell,
        stockQty: safeStock,
        minStockThreshold: safeMin,
        paymentMethod: prodPaymentMethod,
        status: computedStatus,
        updatedAt: nowTs,
      };

      setProducts((prev) => {
        const nextList = prev.map((item) =>
          item.productId === editingProduct.productId ? updatedProd : item
        );
        try {
          localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(nextList));
        } catch {
          // ignore
        }
        return nextList;
      });

      if (stockDelta !== 0) {
        const movId = `mov_in_${Date.now()}`;
        const newMov: StockMovement = {
          movementId: movId,
          orgId: ORG_ID,
          movementCode: `NK-365MD-${String(movements.length + 1).padStart(4, '0')}`,
          productId: editingProduct.productId,
          productSku: cleanSku || editingProduct.productId,
          productName: cleanName,
          type: stockDelta > 0 ? 'inbound' : 'adjustment',
          quantityDelta: stockDelta,
          stockBefore: editingProduct.stockQty,
          stockAfter: safeStock,
          unitValueVnd: safeCost,
          partnerOrReason: sanitizeString(
            `Nhập kho từ NCC: ${cleanSupplier || 'Chưa cập nhật'} | HTTT: ${prodPaymentMethod} (Ngày: ${cleanBatch})`,
            VALIDATION_RULES.PARTNER_REASON_MAX_LEN
          ),
          status: 'completed',
          createdBy: creatorUid,
          createdByName: creatorName,
          createdAt: nowTs,
          updatedAt: nowTs,
        };
        setMovements((prev) => [newMov, ...prev]);
      }

      try {
        await setDoc(
          doc(db, 'products', editingProduct.productId),
          serializeProductForFirestore(updatedProd),
          { merge: true }
        );
      } catch {
        // Local state updated
      }

      notify(
        'success',
        `Đã cập nhật & đồng bộ hàng hóa [${cleanName}] (HTTT: ${prodPaymentMethod}) trên toàn hệ thống Mobile & PC!`
      );
      setEditingProduct(null);
      setShowProdSuggestions(false);
      setShowNewProductModal(false);
    } else {
      const productId = `prod_${Date.now()}`;
      const newProd: Product = {
        productId,
        orgId: ORG_ID,
        sku: cleanSku,
        name: cleanName,
        supplier: cleanSupplier,
        category: prodCategory,
        unit: prodUnit,
        warehouseZone: prodZone,
        batchNumber: cleanBatch,
        costPriceVnd: safeCost,
        sellPriceVnd: safeSell,
        stockQty: safeStock,
        minStockThreshold: safeMin,
        paymentMethod: prodPaymentMethod,
        status: computedStatus,
        createdBy: creatorUid,
        createdAt: nowTs,
        updatedAt: nowTs,
      };

      setProducts((prev) => {
        const nextList = [newProd, ...prev];
        try {
          localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(nextList));
        } catch {
          // ignore
        }
        return nextList;
      });

      if (safeStock > 0) {
        const movId = `mov_new_${Date.now()}`;
        const newMov: StockMovement = {
          movementId: movId,
          orgId: ORG_ID,
          movementCode: `NK-365MD-${String(movements.length + 1).padStart(4, '0')}`,
          productId,
          productSku: cleanSku || productId,
          productName: cleanName,
          type: 'inbound',
          quantityDelta: safeStock,
          stockBefore: 0,
          stockAfter: safeStock,
          unitValueVnd: safeCost,
          partnerOrReason: sanitizeString(
            `Nhập kho mã mới từ NCC: ${cleanSupplier || 'Chưa cập nhật'} | HTTT: ${prodPaymentMethod} (Ngày: ${cleanBatch})`,
            VALIDATION_RULES.PARTNER_REASON_MAX_LEN
          ),
          status: 'completed',
          createdBy: creatorUid,
          createdByName: creatorName,
          createdAt: nowTs,
          updatedAt: nowTs,
        };
        setMovements((prev) => [newMov, ...prev]);
      }

      try {
        await setDoc(doc(db, 'products', productId), serializeProductForFirestore(newProd), {
          merge: true,
        });
      } catch {
        // Local state updated
      }

      notify(
        'success',
        `Đã thêm sản phẩm mới [${cleanName}] (HTTT: ${prodPaymentMethod}) và đồng bộ trên toàn hệ thống!`
      );
      setShowProdSuggestions(false);
      setShowNewProductModal(false);
    }
  };

  const handleInlineUpdateProduct = async (
    product: Product,
    updates: Partial<Product>,
    showToast = false
  ) => {
    const nowTs = Timestamp.now();
    const nextStock =
      updates.stockQty !== undefined
        ? Math.max(-100000, Math.min(1000000, Number(updates.stockQty) || 0))
        : product.stockQty;
    const nextCost =
      updates.costPriceVnd !== undefined
        ? Math.max(0, Math.min(10000000000, Math.round(Number(updates.costPriceVnd) || 0)))
        : product.costPriceVnd;
    const nextSell =
      updates.sellPriceVnd !== undefined
        ? Math.max(0, Math.min(10000000000, Math.round(Number(updates.sellPriceVnd) || 0)))
        : product.sellPriceVnd;
    const nextSku =
      updates.sku !== undefined ? updates.sku.trim().slice(0, 80) : product.sku;
    const nextName =
      updates.name !== undefined
        ? updates.name.trim().slice(0, 120) || product.name
        : product.name;
    const nextSupplier =
      updates.supplier !== undefined
        ? normalizeSupplierShortName(updates.supplier.trim().slice(0, 100))
        : product.supplier;
    const nextBatch =
      updates.batchNumber !== undefined
        ? updates.batchNumber.trim().slice(0, 40) || product.batchNumber
        : product.batchNumber;

    const updatedProd: Product = {
      ...product,
      sku: nextSku,
      name: nextName,
      supplier: nextSupplier,
      batchNumber: nextBatch,
      costPriceVnd: nextCost,
      sellPriceVnd: nextSell,
      stockQty: nextStock,
      status: computeProductStatus(nextStock, product.minStockThreshold),
      updatedAt: nowTs,
    };

    if (nextSupplier && !STANDARD_SUPPLIERS_365MD.includes(nextSupplier)) {
      setCustomSuppliers((prev) => (prev.includes(nextSupplier) ? prev : [...prev, nextSupplier]));
    }

    setProducts((prev) => {
      const nextList = prev.map((item) =>
        item.productId === product.productId ? updatedProd : item
      );
      try {
        localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });

    try {
      await setDoc(
        doc(db, 'products', product.productId),
        serializeProductForFirestore(updatedProd),
        { merge: true }
      );
    } catch {
      // Local state updated
    }

    if (showToast) {
      notify(
        'success',
        `Đã lưu & đồng bộ hàng hóa [${updatedProd.name}] trên toàn hệ thống Mobile & PC!`
      );
    }
  };

  const handleDeleteProduct = async (product: Product) => {
    if (!effectivePermissions.permInventoryEdit) {
      notify('error', 'Từ chối truy cập: Bạn không có quyền xóa mã sản phẩm kho.');
      return;
    }
    setProducts((prev) => {
      const nextList = prev.filter((p) => p.productId !== product.productId);
      try {
        localStorage.setItem(STORAGE_KEYS.PRODUCTS, JSON.stringify(nextList));
      } catch {
        // ignore
      }
      return nextList;
    });
    try {
      await deleteDoc(doc(db, 'products', product.productId));
    } catch {
      // ignore
    }
    notify('info', `Đã xóa sản phẩm [${product.name}] khỏi danh mục kho.`);
  };

  const handleCreateStockMovement = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!effectivePermissions.permInventoryEdit && !effectivePermissions.permStockApprove) {
      notify(
        'error',
        'Từ chối truy cập: Tài khoản của bạn cần quyền [Sửa Kho] hoặc [Duyệt Phiếu] để lập phiếu nhập xuất kho.'
      );
      return;
    }

    const targetProduct = products.find((p) => p.productId === slipProductId);
    if (!targetProduct) {
      notify('error', 'Vui lòng thêm sản phẩm vào kho trước khi lập phiếu nhập/xuất.');
      return;
    }

    const absQty = Math.max(1, Math.min(100000, Math.round(Number(slipQty) || 1)));
    const signedDelta =
      slipType === 'outbound' ? -absQty : slipType === 'inbound' ? absQty : Number(slipQty);
    const projectedStock = targetProduct.stockQty + signedDelta;

    if (projectedStock < 0) {
      notify(
        'error',
        `Số lượng xuất vượt quá tồn kho hiện tại (${targetProduct.stockQty} ${targetProduct.unit}).`
      );
      return;
    }

    const canFinalizeNow = slipImmediateApprove && effectivePermissions.permStockApprove;
    const movementId = `mov_${Date.now()}`;
    const prefix = slipType === 'inbound' ? 'NK' : slipType === 'outbound' ? 'XK' : 'KK';
    const movementCode = `${prefix}-365MD-${String(movements.length + 1).padStart(4, '0')}`;
    const nowTs = Timestamp.now();
    const operatorUid = firebaseUser?.uid || currentAccount?.staffId || 'acc_admin_365md';
    const operatorName = sanitizeString(
      currentAccount?.fullName || 'Quản trị viên 365MD',
      VALIDATION_RULES.FULL_NAME_MAX_LEN
    );

    const newMov: StockMovement = {
      movementId,
      orgId: ORG_ID,
      movementCode,
      productId: targetProduct.productId,
      productSku: targetProduct.sku,
      productName: targetProduct.name,
      type: slipType,
      quantityDelta: signedDelta,
      stockBefore: targetProduct.stockQty,
      stockAfter: projectedStock,
      unitValueVnd: targetProduct.costPriceVnd,
      partnerOrReason: sanitizeString(
        slipReason,
        VALIDATION_RULES.PARTNER_REASON_MAX_LEN,
        'Giao dịch kho nội bộ 365MD'
      ),
      status: canFinalizeNow ? 'completed' : 'pending',
      createdBy: operatorUid,
      createdByName: operatorName,
      createdAt: nowTs,
      updatedAt: nowTs,
    };

    setMovements((prev) => [newMov, ...prev]);

    if (canFinalizeNow) {
      setProducts((prev) =>
        prev.map((p) =>
          p.productId === targetProduct.productId
            ? {
                ...p,
                stockQty: projectedStock,
                status: computeProductStatus(projectedStock, p.minStockThreshold),
                updatedAt: nowTs,
              }
            : p
        )
      );
    }

    try {
      await setDoc(doc(db, 'stock_movements', movementId), {
        ...newMov,
        createdBy: operatorUid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
      if (canFinalizeNow) {
        await setDoc(
          doc(db, 'products', targetProduct.productId),
          {
            ...targetProduct,
            stockQty: projectedStock,
            status: computeProductStatus(projectedStock, targetProduct.minStockThreshold),
            updatedAt: serverTimestamp(),
          },
          { merge: true }
        );
      }
    } catch {
      // Local state updated
    }

    notify(
      'success',
      canFinalizeNow
        ? `Đã lập và duyệt phiếu [${movementCode}] — Tồn kho mới của ${targetProduct.sku}: ${projectedStock} ${targetProduct.unit}.`
        : `Đã lập phiếu [${movementCode}] ở trạng thái Chờ phê duyệt.`
    );
    setSlipReason('');
    setShowStockSlipModal(false);
  };

  const handleResolvePendingMovement = async (
    mov: StockMovement,
    nextStatus: 'completed' | 'cancelled'
  ) => {
    if (!effectivePermissions.permStockApprove) {
      notify(
        'error',
        'Từ chối truy cập: Chỉ tài khoản có quyền [Duyệt Phiếu] (permStockApprove) mới được phê duyệt phiếu kho.'
      );
      return;
    }
    if (mov.status !== 'pending') return;

    const nowTs = Timestamp.now();
    const targetProduct = products.find((p) => p.productId === mov.productId);
    const updatedReason = sanitizeString(
      `${mov.partnerOrReason} (${nextStatus === 'completed' ? 'Đã duyệt' : 'Đã hủy'})`,
      VALIDATION_RULES.PARTNER_REASON_MAX_LEN
    );

    setMovements((prev) =>
      prev.map((m) =>
        m.movementId === mov.movementId
          ? { ...m, status: nextStatus, partnerOrReason: updatedReason, updatedAt: nowTs }
          : m
      )
    );

    if (nextStatus === 'completed' && targetProduct) {
      const newStock = Math.max(0, targetProduct.stockQty + mov.quantityDelta);
      setProducts((prev) =>
        prev.map((p) =>
          p.productId === targetProduct.productId
            ? {
                ...p,
                stockQty: newStock,
                status: computeProductStatus(newStock, p.minStockThreshold),
                updatedAt: nowTs,
              }
            : p
        )
      );
    }

    try {
      await setDoc(
        doc(db, 'stock_movements', mov.movementId),
        {
          ...mov,
          status: nextStatus,
          partnerOrReason: updatedReason,
          updatedAt: serverTimestamp(),
        },
        { merge: true }
      );
      if (nextStatus === 'completed' && targetProduct) {
        const newStock = Math.max(0, targetProduct.stockQty + mov.quantityDelta);
        await setDoc(
          doc(db, 'products', targetProduct.productId),
          {
            ...targetProduct,
            stockQty: newStock,
            status: computeProductStatus(newStock, targetProduct.minStockThreshold),
            updatedAt: serverTimestamp(),
          },
          { merge: true }
        );
      }
    } catch {
      // Local state updated
    }

    notify(
      'success',
      nextStatus === 'completed'
        ? `Đã phê duyệt phiếu kho [${mov.movementCode}] và cập nhật tồn kho thực tế.`
        : `Đã hủy phiếu kho [${mov.movementCode}].`
    );
  };

