  // POS & WORK ORDER ("LẬP HÓA ĐƠN THI CÔNG") HANDLERS
  // =========================================================================
  const handleAddQuickTechnician = () => {
    const clean = quickNewTechName.trim();
    if (!clean) {
      notify('error', 'Vui lòng nhập tên Kỹ thuật viên cần thêm.');
      return;
    }
    const names = clean
      .split(/[\n,;]+/)
      .map((s) => s.trim())
      .filter(Boolean);

    if (quickNewTechRole === 'MAIN' || quickNewTechRole === 'BOTH') {
      setMainTechniciansList((prev) => Array.from(new Set([...prev, ...names])));
    }
    if (quickNewTechRole === 'SUB' || quickNewTechRole === 'BOTH') {
      setSubTechniciansList((prev) => Array.from(new Set([...prev, ...names])));
    }
    setQuickNewTechName('');
    notify(
      'success',
      `Đã thêm ${names.length} kỹ thuật viên (${names.join(', ')}) vào danh sách thi công!`
    );
  };

