    setSaleCarModel('');
    setSaleCustomerRef('');
    setSelectedMainTechs([]);
    setSelectedSubTechs([]);
    setSaleExternalTech('');
    setSaleHasWindowTint(false);
    setSaleWindowTintNote('');
    setSaleDiscountVnd(0);
