                          const isPlate = !c.customerCode.toUpperCase().startsWith('KH');
                          const custOrders = customerOrdersMap.get(c.customerId) || [];
                          const hasUsedService = custOrders.length > 0;
                          const isExpanded = expandedCustomerIdInTable === c.customerId;
                          const totalCustRevenue = custOrders
                            .filter((o) => o.status !== 'refunded')
                            .reduce((sum, o) => sum + o.totalRevenueVnd, 0);
                          const latestOrd = custOrders[0];
                          const latestExt = latestOrd
                            ? orderWorkDetailsMap[latestOrd.orderId]
                            : undefined;
                          const latestInstallDate = latestOrd
                            ? latestExt?.createdDateDisplay || formatTimestamp(latestOrd.createdAt)
                            : c.lastTransactionDateStr;
                          const latestWarranties = Array.from(
                            new Set(
                              custOrders.flatMap((o) => {
                                const ext = orderWorkDetailsMap[o.orderId];
                                if (ext?.serviceLines && ext.serviceLines.length > 0) {
                                  return ext.serviceLines
                                    .map((l) => l.warrantyPeriod)
                                    .filter(Boolean) as string[];
                                }
                                if (ext?.warrantySummary) return [ext.warrantySummary];
                                const m = o.itemsSummary.match(/\(BH:\s*([^)]+)\)/i);
                                return m ? [m[1]] : ['12 tháng'];
                              })
                            )
                          ).join(', ');

